  function proposalRows(){return CASE_PROPOSALS.map(function(p){var o=opportunity(p.opportunityId);var scopes=CASE_SCOPE_ITEMS.filter(function(s){return s.proposalId===p.id&&!s.archived;});return '<tr><td><button class="case49-link" onclick="case49ProposalOpen(\''+E(p.id)+'\')"><b>'+E(p.number||p.title)+'</b></button><small>Версия '+E(p.version||'1.0')+'</small></td><td>'+E(o?o.projectName:p.projectName||'—')+'<small>'+E(o?clientName(o.clientId):clientName(p.clientId))+'</small></td><td>'+badge(label(PROPOSAL_STATUSES,p.status),statusClass(p.status))+'</td><td>'+scopes.length+'</td><td>'+money(p.totalFee,p.currency)+'</td><td>'+fmtDate(p.validUntil)+'</td><td><div class="case49-row-actions"><button class="btn ghost sm" onclick="case492EditProposal(\''+E(p.id)+'\')">Конструктор</button><button class="btn ghost sm" onclick="case49ProposalOpen(\''+E(p.id)+'\')">Открыть</button><button class="btn ghost sm" onclick="case49ProposalClone(\''+E(p.id)+'\')">Новая версия</button><button class="btn ghost sm" onclick="case49ContractFromProposal(\''+E(p.id)+'\')">Договор</button></div></td></tr>';}).join('');}
