  window.case49ScopeItemEdit=function(id,proposalId){var s=id?scopeItem(id):null;s=s||{proposalId:proposalId,serviceType:'generic',department:'Advisory',durationDays:5,plannedHours:16,order:CASE_SCOPE_ITEMS.filter(function(x){return x.proposalId===proposalId;}).length+1,iterations:2};var body='<div class="case49-form-grid">'+field('Название работы','c49_scope_title',s.title)+selectField('Тип услуги / шаблон задач','c49_scope_type',options(SERVICE_TYPES,s.serviceType))+selectField('Ответственное направление','c49_scope_dept',options(DEPARTMENTS.map(function(x){return [x,x];}),s.department))+field('Результат / deliverable','c49_scope_deliv',s.deliverable)+field('Срок, рабочих дней','c49_scope_days',s.durationDays,'number','min="1"')+field('Плановые часы','c49_scope_hours',s.plannedHours,'number','min="0" step="0.5"')+field('Цена работы','c49_scope_price',s.price,'number','min="0" step="0.01"')+field('Количество итераций','c49_scope_iterations',s.iterations,'number','min="0"')+field('Порядок','c49_scope_order',s.order,'number','min="1"')+selectField('Предпочтительный исполнитель','c49_scope_assignee',peopleOptions(s.assigneeId,true))+textField('Описание и границы работы','c49_scope_desc',s.description,4)+'</div>';modal(s.id?'Изменить работу Scope':'Новая работа Scope',body,'<button class="btn ghost" onclick="case49CloseModal()">Отмена</button>'+(s.id?'<button class="btn ghost danger" onclick="case49ScopeArchive(\''+E(s.id)+'\')">Исключить</button>':'')+'<button class="btn" onclick="case49ScopeItemSave(\''+E(s.id||'')+'\',\''+E(proposalId||s.proposalId||'')+'\')">Сохранить</button>',true);};
