  function renderContracts(){var rows=CASE_CONTRACTS.map(function(c){var p=proposal(c.proposalId),o=p?opportunity(p.opportunityId):null;return '<tr><td><button class="case49-link" onclick="case49ContractEdit(\''+E(c.id)+'\')"><b>'+E(c.number||'Договор')+'</b></button><small>Версия '+E(c.version||'1.0')+'</small></td><td>'+E(c.projectName||(o&&o.projectName)||'—')+'<small>'+E(clientName(c.clientId||(o&&o.clientId)))+'</small></td><td>'+badge(label(CONTRACT_STATUSES,c.status),statusClass(c.status))+'</td><td>'+money(c.value,c.currency)+'</td><td>'+fmtDate(c.signedDate)+'</td><td>'+E(c.projectId?projectName(c.projectId):'Проект не запущен')+'</td><td><div class="case49-row-actions"><button class="btn ghost sm" onclick="case49ContractEdit(\''+E(c.id)+'\')">Открыть</button>'+((c.status==='signed'||c.status==='active')&&!c.projectId?'<button class="btn sm" onclick="case49ContractLaunch(\''+E(c.id)+'\')">Запустить проект</button>':'')+'</div></td></tr>';}).join('');var body='<div class="case49-toolbar"><span class="case49-note">Договор создаётся из принятого КП и сохраняет снимок Scope.</span><div class="case49-spacer"></div></div>';body+=CASE_CONTRACTS.length?'<div class="card case49-card"><div class="tbl-scroll"><table class="case49-table"><thead><tr><th>Договор</th><th>Проект / клиент</th><th>Статус</th><th>Стоимость</th><th>Подписан</th><th>Связанный проект</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div></div>':empty('▣','Договоров Advisory пока нет','Примите КП и создайте договор. После подписания система автоматически создаст проект, Scope, задачи и deliverables.','<button class="btn" onclick="go(\'advisory_proposals\')">Перейти к КП</button>');return page('Договоры Advisory','Версии, согласование, подписание и автоматический запуск проекта.',body);}
