  function generateFromScope(items,projectId,startDate){var cursor=startDate||todayISO(),created=0;items.sort(function(a,b){return n(a.order)-n(b.order);}).forEach(function(s){s.projectId=projectId;s.status='active';s.baseline=true;s.scopeVersion=s.scopeVersion||'1.0';var bp=blueprint(s),days=Math.max(1,n(s.durationDays)||bp.length),per=Math.max(1,Math.ceil(days/bp.length)),hours=n(s.plannedHours)||bp.length*4;var assignee=bestAssignee(s.department,s.assigneeId);var prev='';bp.forEach(function(title,i){var due=addDays(cursor,Math.min(days,(i+1)*per));var t={id:uid('task'),projectId:projectId,scopeItemId:s.id,title:title,department:s.department||'Advisory',assigneeId:assignee,status:i===0?'ready':'backlog',priority:i===bp.length-1?'high':'normal',startDate:i===0?cursor:addDays(cursor,i*per),dueDate:due,plannedHours:Math.round(hours/bp.length*10)/10,actualHours:0,dependsOn:prev?[prev]:[],createdAt:nowISO(),createdBy:currentUserName()};CASE_TASKS.push(t);prev=t.id;created++;});cursor=addDays(cursor,days);if(s.deliverable){CASE_DELIVERABLES.push({id:uid('del'),projectId:projectId,scopeItemId:s.id,title:s.deliverable,type:/финал|final/i.test(s.deliverable)?'final_report':'deliverable',status:'planned',ownerId:assignee,dueDate:cursor,version:'1.0',createdAt:nowISO()});}});return created;}
  window.case49ContractLaunch=function(id){var c=contract(id);if(!c||c.projectId)return;var p=proposal(c.proposalId),o=p&&opportunity(p.opportunityId);var projectId=o&&o.objectId;var project=projectId&&obj(projectId);if(!project){projectId=uid('proj');project={id:projectId,name:c.projectName||(o&&o.projectName)||c.number,ru:c.projectName||(o&&o.projectName)||c.number,country:'Узбекистан',city:'',type:'Advisory Project',gba:0,gla:0,status:'active',businessLines:['Advisory'],plan:'Свой объект',sc:0,inc:0,cur:'USD',cond:'',levels:'single',vat:'incl',vatRate:12,comm:{type:'flat',total:0,note:''},createdAt:nowISO()};OBJECTS.push(project);if(o)o.objectId=projectId;}c.projectId=projectId;c.status='active';var scopes=CASE_SCOPE_ITEMS.filter(function(s){return s.proposalId===c.proposalId&&!s.archived;});scopes.forEach(function(s){s.contractId=c.id;s.projectId=projectId;s.baselineSnapshot=JSON.parse(JSON.stringify({title:s.title,description:s.description,durationDays:s.durationDays,plannedHours:s.plannedHours,price:s.price,deliverable:s.deliverable,department:s.department}));});var count=generateFromScope(scopes,projectId,c.startDate||todayISO());if(o){o.stage='won';o.projectId=projectId;o.probability=100;}try{rebuildObjSel();}catch(e){}S.obj=projectId;save('Проект запущен',project.name+' · задач: '+count);closeModal();go('project_workspace');};

  /* ── Project workspace ─────────────────────────────────────────── */
  function renderProjectWorkspace(){var pid=selectedProject();if(!pid)return page('Рабочий стол проекта','Единая точка входа для всех участвующих направлений.',empty('◆','Выберите проект','Рабочий стол объединяет Scope, задачи, договоры, планировки, deliverables и решения.',projectPicker('project_workspace')));var o=obj(pid),tasks=CASE_TASKS.filter(function(t){return t.projectId===pid;}),open=tasks.filter(function(t){return ['done','cancelled'].indexOf(t.status)<0;}),late=open.filter(function(t){return t.dueDate&&new Date(t.dueDate+'T23:59:59')<new Date();}),scope=CASE_SCOPE_ITEMS.filter(function(s){return s.projectId===pid&&!s.archived;}),dels=CASE_DELIVERABLES.filter(function(d){return d.projectId===pid;}),layouts=CASE_LAYOUT_VERSIONS.filter(function(l){return l.projectId===pid&&!l.archived;}),contracts=CASE_CONTRACTS.filter(function(c){return c.projectId===pid;});var pct=tasks.length?Math.round(tasks.filter(function(t){return t.status==='done';}).length/tasks.length*100):0;var k='<div class="case49-project-title"><div>'+projectPicker('project_workspace')+'<h2>'+E(o.name||o.ru||o.id)+'</h2><p>'+E((o.businessLines||['Advisory']).join(' · '))+'</p></div>'+badge(pct+'% выполнено',pct===100?'ok':'')+'</div><div class="case49-kpis"><div><b>'+scope.length+'</b><span>работ Scope</span></div><div><b>'+open.length+'</b><span>открытых задач</span></div><div><b class="'+(late.length?'case49-red':'')+'">'+late.length+'</b><span>просрочено</span></div><div><b>'+dels.length+'</b><span>deliverables</span></div></div>';
    var nav='<div class="case49-hub-grid">'+[
      ['advisory_scope','☷','Scope of Work','Договорный объём, версии и изменения'],['work_tasks','✓','Задачи','Таблица, Kanban и сроки'],['project_layouts','▭','Планировки','Оригинал, Leasing-версии и согласования'],['advisory_reports','▤','Deliverables','Черновые и финальные отчёты'],['project_contracts','▣','Договоры','Стоимость, сроки и документы'],['docs','◫','Документы','Общий реестр файлов проекта']
    ].map(function(x){return '<button onclick="go(\''+x[0]+'\')"><span>'+x[1]+'</span><b>'+x[2]+'</b><small>'+x[3]+'</small></button>';}).join('')+'</div>';
    var recent=open.slice().sort(function(a,b){return String(a.dueDate).localeCompare(String(b.dueDate));}).slice(0,8);var list='<div class="card case49-card"><div class="case49-section-head"><div><h3>Ближайшая работа</h3><p>Открытые задачи проекта по сроку.</p></div><button class="btn ghost sm" onclick="go(\'work_tasks\')">Все задачи</button></div>'+(recent.length?recent.map(taskCompact).join(''):empty('✓','Нет открытых задач','Задачи появятся автоматически из Scope или могут быть добавлены вручную.','<button class="btn" onclick="case49TaskEdit()">Добавить задачу</button>'))+'</div>';
    return page('Рабочий стол проекта','Контекст проекта для Advisory, Leasing, Finance и будущего Management.',k+nav+list);
  }

  /* ── Scope and change control ──────────────────────────────────── */
  function renderScope(){var pid=selectedProject();if(!pid)return page('Scope of Work','Договорный объём и управляемые изменения.',empty('☷','Выберите проект','Scope проекта появляется после подписания договора или может быть добавлен вручную.',projectPicker('advisory_scope')));var items=CASE_SCOPE_ITEMS.filter(function(s){return s.projectId===pid&&!s.archived;}).sort(function(a,b){return n(a.order)-n(b.order);});var changes=CASE_SCOPE_CHANGES.filter(function(c){return c.projectId===pid;}).sort(function(a,b){return String(b.createdAt).localeCompare(String(a.createdAt));});var baseline=items.filter(function(s){return s.baseline;}).length,plannedHours=items.reduce(function(a,s){return a+n(s.plannedHours);},0),price=items.reduce(function(a,s){return a+n(s.price);},0);var k='<div class="case49-kpis"><div><b>'+items.length+'</b><span>текущий Scope</span></div><div><b>'+baseline+'</b><span>исходных работ</span></div><div><b>'+plannedHours.toLocaleString('ru-RU')+'</b><span>плановых часов</span></div><div><b>'+money(price,'USD')+'</b><span>распределённая стоимость</span></div></div>';
    var rows=items.map(function(s){var linked=CASE_TASKS.filter(function(t){return t.scopeItemId===s.id;});return '<tr><td>'+n(s.order)+'</td><td><b>'+E(s.title)+'</b><small>'+E(label(SERVICE_TYPES,s.serviceType))+'</small></td><td>'+E(s.department||'—')+'</td><td>'+E(s.deliverable||'—')+'</td><td>'+n(s.durationDays)+' дн.</td><td>'+n(s.plannedHours)+' ч.</td><td>'+linked.length+'</td><td>'+badge(s.baseline?'Исходный':'Изменение',s.baseline?'':'warn')+'</td></tr>';}).join('');var body=k+'<div class="case49-toolbar"><span class="case49-note">Подписанный Scope не перезаписывается. Добавление, исключение или изменение оформляется Change Request.</span><div class="case49-spacer"></div><button class="btn" onclick="case49ScopeChangeEdit()">+ Изменить Scope</button></div>'+(items.length?'<div class="card case49-card"><div class="tbl-scroll"><table class="case49-table"><thead><tr><th>#</th><th>Работа</th><th>Направление</th><th>Deliverable</th><th>Срок</th><th>Часы</th><th>Задач</th><th>Источник</th></tr></thead><tbody>'+rows+'</tbody></table></div></div>':empty('☷','В проекте нет Scope','Добавьте Change Request типа «Добавление», чтобы сформировать первую работу.','<button class="btn" onclick="case49ScopeChangeEdit()">Добавить работу</button>'));
    body+='<div class="card case49-card"><div class="case49-section-head"><div><h3>Изменения Scope</h3><p>Влияние на стоимость, сроки и команду фиксируется до применения.</p></div></div>'+(changes.length?changes.map(function(c){return '<div class="case49-change"><div>'+badge(c.type==='add'?'Добавление':c.type==='remove'?'Исключение':'Изменение',c.type==='remove'?'bad':'warn')+' '+badge(c.status==='approved'?'Согласовано':c.status==='rejected'?'Отклонено':'На согласовании',statusClass(c.status))+'</div><div><b>'+E(c.title||((scopeItem(c.scopeItemId)||{}).title)||'Изменение Scope')+'</b><p>'+E(c.reason||'Причина не указана')+'</p><small>Срок: '+(c.impactDays>=0?'+':'')+n(c.impactDays)+' дн. · Часы: '+(c.impactHours>=0?'+':'')+n(c.impactHours)+' · Стоимость: '+money(c.impactPrice,'USD')+'</small></div>'+(c.status==='pending'&&canApprove()?'<button class="btn sm" onclick="case49ScopeChangeApprove(\''+E(c.id)+'\')">Согласовать</button>':'')+'</div>';}).join(''):empty('◎','Изменений пока нет','История изменений появится здесь.',''))+'</div>';return page('Scope of Work','Исходный договорный Scope, текущая версия и контролируемые изменения.',body);}
  window.case49ScopeChangeEdit=function(){var pid=selectedProject();if(!pid){alert('Сначала выберите проект.');return;}var current=CASE_SCOPE_ITEMS.filter(function(s){return s.projectId===pid&&!s.archived;});var body='<div class="case49-form-grid">'+selectField('Тип изменения','c49_ch_type',options([['add','Добавить работу'],['modify','Изменить работу'],['remove','Исключить работу']],current.length?'modify':'add'))+selectField('Связанная работа','c49_ch_scope','<option value="">Новая работа</option>'+current.map(function(s){return '<option value="'+E(s.id)+'">'+E(s.title)+'</option>';}).join(''))+field('Название / новая формулировка','c49_ch_title','')+selectField('Тип услуги','c49_ch_service',options(SERVICE_TYPES,'generic'))+selectField('Направление','c49_ch_dept',options(DEPARTMENTS.map(function(x){return [x,x];}),'Advisory'))+field('Deliverable','c49_ch_deliv','')+field('Изменение срока, дней','c49_ch_days','0','number')+field('Изменение часов','c49_ch_hours','0','number')+field('Изменение стоимости','c49_ch_price','0','number')+selectField('Коммерческий режим','c49_ch_commercial',options([['included','Входит в текущую стоимость'],['paid','Дополнительная платная работа'],['internal','Внутренняя работа CASE'],['pending','Требуется решение клиента']],'pending'))+textField('Причина и описание изменения','c49_ch_reason','',5)+'</div>';modal('Scope Change Request',body,'<button class="btn ghost" onclick="case49CloseModal()">Отмена</button><button class="btn" onclick="case49ScopeChangeSave()">Отправить на согласование</button>',true);};
  window.case49ScopeChangeSave=function(){var pid=selectedProject(),type=val('c49_ch_type'),target=scopeItem(val('c49_ch_scope'));var title=val('c49_ch_title').trim()||(target&&target.title);if(!title){alert('Укажите название работы или выберите существующую.');return;}var c={id:uid('sch'),projectId:pid,type:type,scopeItemId:target?target.id:'',title:title,serviceType:val('c49_ch_service'),department:val('c49_ch_dept'),deliverable:val('c49_ch_deliv').trim(),impactDays:n(val('c49_ch_days')),impactHours:n(val('c49_ch_hours')),impactPrice:n(val('c49_ch_price')),commercialMode:val('c49_ch_commercial'),reason:val('c49_ch_reason').trim(),status:'pending',createdAt:nowISO(),createdBy:currentUserName(),oldValue:target?JSON.parse(JSON.stringify(target)):null};CASE_SCOPE_CHANGES.push(c);save('Запрос изменения Scope',title);closeModal();go('advisory_scope');};
  window.case49ScopeChangeApprove=function(id){var c=CASE_SCOPE_CHANGES.find(function(x){return x.id===id;});if(!c||!canApprove())return;if(!confirm('Согласовать и применить изменение Scope?'))return;var target=scopeItem(c.scopeItemId);if(c.type==='add'){target={id:uid('scope'),projectId:c.projectId,title:c.title,serviceType:c.serviceType,department:c.department,deliverable:c.deliverable,durationDays:Math.max(1,c.impactDays||5),plannedHours:Math.max(0,c.impactHours),price:c.impactPrice,order:CASE_SCOPE_ITEMS.filter(function(s){return s.projectId===c.projectId&&!s.archived;}).length+1,status:'active',baseline:false,scopeVersion:'change',createdAt:nowISO(),originChangeId:c.id};CASE_SCOPE_ITEMS.push(target);generateFromScope([target],c.projectId,todayISO());}else if(c.type==='remove'&&target){target.status='excluded';target.archived=true;CASE_TASKS.filter(function(t){return t.scopeItemId===target.id&&t.status!=='done';}).forEach(function(t){t.status='cancelled';t.cancelReason='Scope исключён';});}else if(c.type==='modify'&&target){target.title=c.title||target.title;target.serviceType=c.serviceType||target.serviceType;target.department=c.department||target.department;target.deliverable=c.deliverable||target.deliverable;target.durationDays=Math.max(1,n(target.durationDays)+n(c.impactDays));target.plannedHours=Math.max(0,n(target.plannedHours)+n(c.impactHours));target.price=n(target.price)+n(c.impactPrice);target.baseline=false;target.updatedAt=nowISO();}c.status='approved';c.approvedAt=nowISO();c.approvedBy=currentUserName();save('Scope Change согласован',c.title);go('advisory_scope');};

  /* ── Tasks: table, Kanban, assignment, workload ───────────────── */
  function taskAllowed(t,myOnly){if(myOnly&&String(t.assigneeId)!==currentUserKey()&&String(t.assigneeId)!==String(currentUserName()))return false;if(UI.taskProject&&t.projectId!==UI.taskProject)return false;if(UI.taskStatus&&t.status!==UI.taskStatus)return false;if(UI.taskDept&&t.department!==UI.taskDept)return false;if(UI.taskAssignee&&String(t.assigneeId)!==String(UI.taskAssignee))return false;if(UI.taskSearch){var q=UI.taskSearch.toLowerCase(),hay=(t.title+' '+projectName(t.projectId)+' '+personName(t.assigneeId)).toLowerCase();if(hay.indexOf(q)<0)return false;}return true;}
  function taskToolbar(route,myOnly){return '<div class="case49-toolbar case49-task-toolbar"><div class="case49-segment"><button class="'+(UI.taskMode==='table'?'on':'')+'" onclick="case49TaskMode(\'table\',\''+route+'\')">Таблица</button><button class="'+(UI.taskMode==='kanban'?'on':'')+'" onclick="case49TaskMode(\'kanban\',\''+route+'\')">Kanban</button></div><div class="case49-search"><span>⌕</span><input value="'+E(UI.taskSearch)+'" placeholder="Поиск задачи…" oninput="case49TaskFilter(\'search\',this.value,\''+route+'\')"></div><select onchange="case49TaskFilter(\'project\',this.value,\''+route+'\')">'+projectOptions(UI.taskProject,true)+'</select><select onchange="case49TaskFilter(\'status\',this.value,\''+route+'\')"><option value="">Все статусы</option>'+options(TASK_STATUSES,UI.taskStatus)+'</select><select onchange="case49TaskFilter(\'dept\',this.value,\''+route+'\')"><option value="">Все отделы</option>'+options(DEPARTMENTS.map(function(x){return [x,x];}),UI.taskDept)+'</select><div class="case49-spacer"></div><button class="btn" onclick="case49TaskEdit()">+ Задача</button></div>'+(UI.selectedTasks.length?'<div class="case49-selection"><b>Выбрано: '+UI.selectedTasks.length+'</b><button class="btn ghost sm" onclick="case49BulkAssign()">Переназначить</button><button class="btn ghost sm" onclick="case49BulkStatus()">Изменить статус</button><button class="btn ghost sm" onclick="case49TaskClearSelection()">Снять выбор</button></div>':'');}
  function taskCompact(t){return '<button class="case49-task-compact" onclick="case49TaskEdit(\''+E(t.id)+'\')"><span class="case49-dot '+statusClass(t.status)+'"></span><span><b>'+E(t.title)+'</b><small>'+E(personName(t.assigneeId))+' · '+E(t.department||'—')+'</small></span><em class="'+deadlineClass(t.dueDate,t.status)+'">'+fmtDate(t.dueDate)+'</em></button>';}
  function taskTable(rows){return '<div class="card case49-card"><div class="tbl-scroll"><table class="case49-table case49-task-table"><thead><tr><th></th><th>Задача</th><th>Проект</th><th>Отдел</th><th>Исполнитель</th><th>Начало</th><th>Дедлайн</th><th>Статус</th><th>Часы</th></tr></thead><tbody>'+rows.map(function(t){var dep=(t.dependsOn||[]).map(task).filter(Boolean).map(function(x){return x.title;}).join(', ');return '<tr class="'+deadlineClass(t.dueDate,t.status)+'"><td><input type="checkbox" '+(UI.selectedTasks.indexOf(t.id)>=0?'checked':'')+' onchange="case49TaskSelect(\''+E(t.id)+'\',this.checked)"></td><td><button class="case49-link" onclick="case49TaskEdit(\''+E(t.id)+'\')"><b>'+E(t.title)+'</b></button><small>'+E((scopeItem(t.scopeItemId)||{}).title||'Внутренняя задача')+(dep?' · после: '+E(dep):'')+'</small></td><td>'+E(projectName(t.projectId))+'</td><td>'+E(t.department||'—')+'</td><td><select onchange="case49TaskReassign(\''+E(t.id)+'\',this.value)">'+peopleOptions(t.assigneeId,true)+'</select></td><td>'+fmtDate(t.startDate)+'</td><td><b>'+fmtDate(t.dueDate)+'</b></td><td><select onchange="case49TaskQuick(\''+E(t.id)+'\',\'status\',this.value)">'+options(TASK_STATUSES,t.status)+'</select></td><td>'+n(t.actualHours)+' / '+n(t.plannedHours)+'</td></tr>';}).join('')+'</tbody></table></div></div>';}
  function taskKanban(rows){return '<div class="case49-kanban case49-task-kanban">'+TASK_STATUSES.filter(function(s){return s[0]!=='cancelled';}).map(function(st){var a=rows.filter(function(t){return t.status===st[0];});return '<section class="case49-kanban-col" ondragover="event.preventDefault()" ondrop="case49TaskDrop(event,\''+st[0]+'\')"><header><div><b>'+E(st[1])+'</b><small>'+a.length+' задач</small></div></header><div class="case49-kanban-stack">'+a.map(function(t){return '<article class="case49-kanban-card '+deadlineClass(t.dueDate,t.status)+'" draggable="true" ondragstart="case49TaskDrag(event,\''+E(t.id)+'\')" onclick="case49TaskEdit(\''+E(t.id)+'\')"><div class="case49-card-top"><b>'+E(t.title)+'</b>'+badge(t.priority==='high'?'Высокий':t.priority==='critical'?'Критический':'',t.priority==='critical'?'bad':t.priority==='high'?'warn':'')+'</div><p>'+E(projectName(t.projectId))+'</p><div class="case49-card-meta"><span>'+E(personName(t.assigneeId))+'</span><span>'+fmtDate(t.dueDate)+'</span></div><div class="case49-progress"><i style="width:'+Math.min(100,Math.round(n(t.actualHours)/Math.max(1,n(t.plannedHours))*100))+'%"></i></div></article>';}).join('')+'</div></section>';}).join('')+'</div>';}
  function renderTasks(route,myOnly,forceKanban){if(forceKanban)UI.taskMode='kanban';var rows=CASE_TASKS.filter(function(t){return taskAllowed(t,myOnly);}).sort(function(a,b){return String(a.dueDate).localeCompare(String(b.dueDate));});var late=rows.filter(function(t){return deadlineClass(t.dueDate,t.status)==='late';}).length,unassigned=rows.filter(function(t){return !t.assigneeId;}).length;var k='<div class="case49-kpis"><div><b>'+rows.length+'</b><span>задач в выборке</span></div><div><b>'+rows.filter(function(t){return t.status==='doing';}).length+'</b><span>в работе</span></div><div><b class="'+(late?'case49-red':'')+'">'+late+'</b><span>просрочено</span></div><div><b>'+unassigned+'</b><span>не назначено</span></div></div>';var title=myOnly?'Мои задачи':'Все задачи';var body=k+taskToolbar(route,myOnly)+(rows.length?(UI.taskMode==='kanban'?taskKanban(rows):taskTable(rows)):empty('✓','Задач не найдено','Измените фильтры или добавьте новую задачу. Задачи также создаются автоматически из Scope.','<button class="btn" onclick="case49TaskEdit()">Добавить задачу</button>'));return page(title,'Один реестр задач с табличным, Kanban и ресурсным представлениями.',body);}
  window.case49TaskMode=function(m,route){UI.taskMode=m;go(route);};
  window.case49TaskFilter=function(k,v,route){if(k==='search')UI.taskSearch=v;if(k==='project')UI.taskProject=v;if(k==='status')UI.taskStatus=v;if(k==='dept')UI.taskDept=v;clearTimeout(window._case49FilterT);window._case49FilterT=setTimeout(function(){go(route);},k==='search'?180:0);};
  window.case49TaskSelect=function(id,on){var i=UI.selectedTasks.indexOf(id);if(on&&i<0)UI.selectedTasks.push(id);if(!on&&i>=0)UI.selectedTasks.splice(i,1);go(S.view);};
  window.case49TaskClearSelection=function(){UI.selectedTasks=[];go(S.view);};
